"""Ordinary-user preparation only: no SDK initialization or kernel operations."""
import argparse
import base64
import hashlib
import json
import os
from pathlib import Path
import platform
import stat
import struct
import subprocess
import sys
import zlib

# Filled by the local packager from the pinned public core commit.
CORE_COMMIT = 'eede9fa0f139ca35ccee8e0723f10413655803d9'
PACKAGE_SHA256 = '3a37f201f920b1d794d567742dd569d40f2bdb583c004c4af85f3b8fca9fb930'
PACKAGE = ''
ADAPTER_SOURCE_SHA256 = '867ba18e0be748dbf9c3d081c45f8536be6630adbe98390dc9aaae78aff91e7a'
SDK_SHA256 = '88686bc4e869c6442eb7d88128a2d3efd82468696c489734fc80b4692ac60223'
MIB = 1024 ** 2


def need(value, reason):
    if not value:
        raise RuntimeError(reason)


def read(path, limit):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    with os.fdopen(fd,'rb') as stream:
        info=os.fstat(stream.fileno())
        need(stat.S_ISREG(info.st_mode) and 0<=info.st_size<=limit,'Invalid bounded input: '+str(path))
        value=stream.read(limit+1)
        need(len(value)<=limit,'Input too large')
        return value


def digest(path):
    return hashlib.sha256(read(path,16*MIB)).hexdigest()


def load(path):
    return json.loads(read(path,MIB))


def put(path,value):
    with path.open('x',encoding='utf-8') as stream:
        json.dump(value,stream,indent=2);stream.write('\n');stream.flush();os.fsync(stream.fileno())


def ordinary(root):
    need(sys.platform=='linux' and platform.machine()=='aarch64','Linux ARM64 preparation required')
    need(os.getuid()==os.geteuid()!=0,'Run as the ordinary SDK owner, not root')
    caps=[line.split()[1] for line in Path('/proc/self/status').read_text().splitlines()
          if line.startswith(('CapInh:','CapPrm:','CapEff:','CapAmb:'))]
    need(len(caps)==4 and not any(int(v,16) for v in caps),'Ordinary UID with zero capabilities required')
    info=root.stat()
    need(root.is_absolute() and root.resolve(strict=True)==root and info.st_uid==os.getuid()
         and not info.st_mode&0o022,'Expected owned workspace without symlink redirection')
    need(os.sysconf('SC_PAGE_SIZE')==4096,'Prepared ext4 image requires the target 4KiB page configuration')
    need(digest(Path('/usr/lib64/libubsm_sdk.so').resolve(strict=True))==SDK_SHA256,
         'Existing SDK library differs; preserved, no install or SDK call')


def find_adapter(root):
    found=[]
    for path in sorted((root/'r').glob('*/libaenv-ub.so')):
        # Inspect only retained preparation artifacts, not another service's process.
        parent=path.parent
        try:
            need(parent.resolve(strict=True)==parent and parent.stat().st_uid==os.getuid(), 'Foreign adapter parent')
            source=read(parent/'adapter.cpp',MIB).decode('utf-8').replace('\r\n','\n').encode()
            need(hashlib.sha256(source).hexdigest()==ADAPTER_SOURCE_SHA256,'Different SDK adapter source')
            prepared=load(parent/'prepared.json');config=load(parent/'config.json')
            actual=digest(path)
            need(prepared.get('adapterSha256','').removeprefix('sha256:')==actual,'Adapter pin differs')
            need(config.get('adapter')==str(path) and config.get('adapterSha256')=='sha256:'+actual,'Config adapter differs')
            region=config.get('region')
            need(isinstance(region,str) and 0<len(region.encode())<128 and '\0' not in region,'Invalid retained region')
            elf=read(path,16*MIB)
            need(elf[:6]==b'\x7fELF\x02\x01' and int.from_bytes(elf[18:20],'little')==183,'Adapter is not ARM64 ELF')
            found.append({'path':str(path),'sha256':actual,'sourceSha256':ADAPTER_SOURCE_SHA256,
                          'preparedRecordSha256':digest(parent/'prepared.json'),'region':region})
        except (OSError,ValueError,RuntimeError,UnicodeError):
            continue
    need(found,'No retained exact-source adapter/config pair found; no new build or SDK call')
    # Every candidate is pinned to its own successful preparation/config. Reuse
    # one deterministic artifact rather than rebuilding or changing old files.
    return found[0]


def system_tool(name):
    for directory in ('/usr/sbin','/sbin','/usr/bin','/bin'):
        path=Path(directory)/name
        if path.is_file():
            info=path.resolve(strict=True).stat()
            need(info.st_uid==0 and not info.st_mode&0o022,'Unsafe system tool')
            return str(path)
    raise RuntimeError('Missing preparation tool: '+name)


def make_image(work, tool):
    seed=work/'seed';seed.mkdir(mode=0o700)
    payload=seed/'payload.bin';sha=hashlib.sha256()
    with payload.open('xb') as output:
        for _ in range(8):
            data=os.urandom(MIB);output.write(data);sha.update(data)
        output.flush();os.fsync(output.fileno())
    image=work/'host-dax-test.ext4'
    with image.open('xb') as output:
        output.truncate(64*MIB);output.flush();os.fsync(output.fileno())
    info=image.lstat()
    need(stat.S_ISREG(info.st_mode) and info.st_uid==os.getuid() and info.st_size==64*MIB,
         'Test image is not the newly created owned regular file')
    result=subprocess.run([tool,'-q','-F','-t','ext4','-b','4096','-m','0',
                           '-O','^has_journal,^inline_data','-E','lazy_itable_init=0,lazy_journal_init=0',
                           '-d',str(seed),str(image)],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,
                          timeout=120,env={'PATH':'/usr/sbin:/sbin:/usr/bin:/bin','LANG':'C','LC_ALL':'C'})
    (work/'mke2fs.log').write_bytes(result.stdout)
    need(result.returncode==0,'Test-container preparation failed; preserve outputs')
    need(image.lstat().st_size==64*MIB and not image.is_symlink(),'Formatted test image differs')
    with image.open('r+b') as stream:
        os.fsync(stream.fileno());stream.seek(1024);superblock=stream.read(1024)
    need(len(superblock)==1024 and struct.unpack_from('<H',superblock,56)[0]==0xef53
         and struct.unpack_from('<I',superblock,24)[0]==2
         and struct.unpack_from('<I',superblock,4)[0]==64*MIB//4096
         and struct.unpack_from('<H',superblock,58)[0]&1
         and not struct.unpack_from('<I',superblock,92)[0]&4
         and not struct.unpack_from('<I',superblock,96)[0]&0x8000,
         'Test ext4 superblock does not match clean 4KiB no-journal/no-inline layout')
    return image,{'name':'payload.bin','bytes':8*MIB,'sha256':sha.hexdigest()}


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode',choices=('plan','prepare'))
    parser.add_argument('--node',required=True,choices=('node-a','node-b'))
    args=parser.parse_args()
    root=Path.cwd();ordinary(root);adapter=find_adapter(root)
    work=root/'r'/('hpmem-a-v1' if args.node=='node-a' else 'hpmem-b-v1')
    need((root/'r').resolve(strict=True)==root/'r' and (root/'r').stat().st_uid==os.getuid(),
         'Expected existing owned r directory')
    tool=system_tool('mke2fs') if args.node=='node-a' else None
    summary={'status':'HOST_PMEM_PREPARATION_PLAN_NO_SDK','node':args.node,'coreCommit':CORE_COMMIT,
             'workspace':str(root),'workDirectory':str(work),'adapter':adapter,
             'kernelRelease':platform.release(),'uid':os.getuid(),'gid':os.getgid(),
             'logicalUbRequestBytes':64*MIB,'postMapCoverageGuardBytes':256*MIB,
             'physicalHardQuota':False,'SDK_called':False,'moduleLoaded':False,'servicesChanged':False,
             'Guest_created':False,'twoNodeAccepted':False,'netSavingsBytes':None}
    if args.mode=='plan':print(json.dumps(summary,indent=2));return
    need(not work.exists() and not work.is_symlink(),'Prior preparation exists; preserved, do not retry')
    packed=zlib.decompress(base64.b64decode(PACKAGE,validate=True))
    need(hashlib.sha256(packed).hexdigest()==PACKAGE_SHA256,'Embedded core package differs')
    modules=json.loads(packed)
    need(isinstance(modules,dict) and modules and all(Path(n).name==n and n.endswith('.py') for n in modules),
         'Invalid embedded core module names')
    work.mkdir(mode=0o700);source=work/'source';source.mkdir(mode=0o700)
    package=source/'aenv_ub_provider';package.mkdir(mode=0o700)
    for name,code in modules.items():
        compile(code,name,'exec');(package/name).write_text(code,encoding='utf-8')
    sys.path.insert(0,str(source))
    from aenv_ub_provider import contract
    if args.node=='node-a':
        image,test=make_image(work,tool)
        spec=contract.make_spec(image,str(work/'provider'/'data.sock'))
        put(work/'catalog.json',{'version':1,'objects':[{'path':str(image),'backing':spec}]})
        summary.update(testFile=test,image=spec)
    summary.update(status='HOST_PMEM_FILES_PREPARED_NO_SDK',packageSha256=PACKAGE_SHA256,
                   adapterRebuilt=False,retainedImagesChanged=False,
                   nextGate='Review complete maintenance/UB-operation plan before execution')
    put(work/'prepared.json',summary)
    print(json.dumps(summary,indent=2))


if __name__=='__main__':
    try:main()
    except Exception as error:
        print(json.dumps({'status':'HOST_PMEM_PREPARATION_STOPPED_PRESERVE_OUTPUTS','reason':str(error),
                          'SDK_called':False,'moduleLoaded':False,'servicesChanged':False}),flush=True)
        raise SystemExit(1)
